#!/usr/bin/env python3
"""
analyze_macho_headers.py
Exhaustive Mach-O static analysis for Apple TV (tvOS 13.4.8) target binaries.
Parses Mach-O headers, load commands, segments, sections, entry points,
UUIDs, build versions, and code signatures.
Strictly static analysis - zero execution of ARM64 binaries.
"""

import os
import sys
import json
import struct
import subprocess
import hashlib

TARGET_BINARIES = {
    "PineBoard": "extracted/rootfs/Applications/PineBoard.app/PineBoard",
    "HeadBoard": "extracted/rootfs/Applications/HeadBoard.app/HeadBoard",
    "PreBoard": "extracted/rootfs/Applications/PreBoard.app/PreBoard",
    "TVMusic": "extracted/rootfs/Applications/TVMusic.app/TVMusic",
    "TVSystemMenuService": "extracted/rootfs/Applications/TVSystemMenuService.app/TVSystemMenuService",
    "TVPeripheralAgent": "extracted/rootfs/Applications/TVPeripheralAgent.app/TVPeripheralAgent",
    "kernelcache": "extracted/kernel/kernelcache.macho",
    "dyld_shared_cache": "extracted/dyld_cache/dyld_shared_cache_arm64",
}

def compute_hashes(filepath):
    sha256 = hashlib.sha256()
    md5 = hashlib.md5()
    size = os.path.getsize(filepath)
    with open(filepath, "rb") as f:
        while chunk := f.read(65536):
            sha256.update(chunk)
            md5.update(chunk)
    return {
        "size_bytes": size,
        "sha256": sha256.hexdigest(),
        "md5": md5.hexdigest()
    }

def parse_macho_header_and_load_commands(filepath):
    """Parse Mach-O header and load commands via llvm-objdump and direct parsing."""
    res = {}

    # Run llvm-objdump --macho --private-headers
    cmd = ["llvm-objdump", "--macho", "--private-headers", filepath]
    proc = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    if proc.returncode != 0:
        return {"error": proc.stderr}

    lines = proc.stdout.splitlines()

    header = {}
    load_commands = []
    current_cmd = None
    current_sect = None

    idx = 0
    while idx < len(lines):
        line = lines[idx]

        if "Mach header" in line:
            # next lines contain header fields
            idx += 2
            if idx < len(lines):
                fields = lines[idx].split()
                if len(fields) >= 8:
                    header = {
                        "magic": fields[0],
                        "cputype": fields[1],
                        "cpusubtype": fields[2],
                        "caps": fields[3],
                        "filetype": fields[4],
                        "ncmds": int(fields[5]),
                        "sizeofcmds": int(fields[6]),
                        "flags": fields[7:]
                    }
            idx += 1
            continue

        if line.startswith("Load command "):
            if current_cmd:
                load_commands.append(current_cmd)
            cmd_num = int(line.split()[2])
            current_cmd = {"command_index": cmd_num, "sections": []}
            current_sect = None
            idx += 1
            continue

        if current_cmd is not None:
            stripped = line.strip()
            if stripped.startswith("cmd "):
                current_cmd["cmd"] = stripped.split()[1]
            elif stripped.startswith("cmdsize "):
                current_cmd["cmdsize"] = int(stripped.split()[1])
            elif stripped.startswith("segname "):
                current_cmd["segname"] = stripped.split()[1]
            elif stripped.startswith("vmaddr "):
                current_cmd["vmaddr"] = stripped.split()[1]
            elif stripped.startswith("vmsize "):
                current_cmd["vmsize"] = stripped.split()[1]
            elif stripped.startswith("fileoff "):
                current_cmd["fileoff"] = int(stripped.split()[1])
            elif stripped.startswith("filesize "):
                current_cmd["filesize"] = int(stripped.split()[1])
            elif stripped.startswith("maxprot "):
                current_cmd["maxprot"] = stripped.split()[1]
            elif stripped.startswith("initprot "):
                current_cmd["initprot"] = stripped.split()[1]
            elif stripped.startswith("nsects "):
                current_cmd["nsects"] = int(stripped.split()[1])
            elif stripped.startswith("flags ") and "segname" in current_cmd:
                current_cmd["segflags"] = stripped.split(None, 1)[1]
            elif stripped.startswith("name ") and current_cmd.get("cmd", "").startswith("LC_LOAD"):
                current_cmd["dylib_path"] = stripped.split()[1]
            elif stripped.startswith("current version "):
                current_cmd["current_version"] = stripped.split()[2]
            elif stripped.startswith("compatibility version "):
                current_cmd["compatibility_version"] = stripped.split()[2]
            elif stripped.startswith("platform "):
                current_cmd["platform"] = stripped.split()[1]
            elif stripped.startswith("minos "):
                current_cmd["minos"] = stripped.split()[1]
            elif stripped.startswith("sdk "):
                current_cmd["sdk"] = stripped.split()[1]
            elif stripped.startswith("entryoff "):
                current_cmd["entryoff"] = stripped.split()[1]
            elif stripped.startswith("stacksize "):
                current_cmd["stacksize"] = stripped.split()[1]
            elif stripped.startswith("uuid "):
                current_cmd["uuid"] = stripped.split()[1]
            elif stripped.startswith("dataoff "):
                current_cmd["dataoff"] = stripped.split()[1]
            elif stripped.startswith("datasize "):
                current_cmd["datasize"] = stripped.split()[1]
            elif stripped.startswith("path ") and current_cmd.get("cmd") == "LC_RPATH":
                current_cmd["rpath"] = stripped.split()[1]
            elif line.startswith("Section"):
                if current_sect:
                    current_cmd["sections"].append(current_sect)
                current_sect = {}
            elif current_sect is not None:
                if stripped.startswith("sectname "):
                    current_sect["sectname"] = stripped.split()[1]
                elif stripped.startswith("segname "):
                    current_sect["segname"] = stripped.split()[1]
                elif stripped.startswith("addr "):
                    current_sect["addr"] = stripped.split()[1]
                elif stripped.startswith("size "):
                    current_sect["size"] = stripped.split()[1]
                elif stripped.startswith("offset "):
                    current_sect["offset"] = int(stripped.split()[1])
                elif stripped.startswith("align "):
                    current_sect["align"] = stripped.split(None, 1)[1]
                elif stripped.startswith("type "):
                    current_sect["type"] = stripped.split()[1]
                elif stripped.startswith("attributes "):
                    current_sect["attributes"] = stripped.split(None, 1)[1]

        idx += 1

    if current_sect and current_cmd is not None:
        current_cmd["sections"].append(current_sect)
    if current_cmd:
        load_commands.append(current_cmd)

    return {
        "header": header,
        "load_commands_count": len(load_commands),
        "load_commands": load_commands
    }

def parse_dyld_cache(filepath):
    """Parse dyld_shared_cache header and image table."""
    with open(filepath, "rb") as f:
        hdr = f.read(128)
        magic = hdr[:16].decode("ascii", errors="replace").strip("\x00")
        mappingOffset, mappingCount, imagesOffset, imagesCount = struct.unpack("<IIII", hdr[16:32])
        dyldBaseAddress, codeSignatureOffset, codeSignatureSize, slideInfoOffset, slideInfoSize = struct.unpack("<QQQQQ", hdr[32:72])

        # Read mappings
        f.seek(mappingOffset)
        mappings = []
        for i in range(mappingCount):
            mbytes = f.read(32)
            address, size, fileOffset, maxProt, initProt = struct.unpack("<QQQII", mbytes)
            mappings.append({
                "mapping_index": i,
                "address": f"0x{address:x}",
                "size_bytes": size,
                "size_mb": round(size / (1024 * 1024), 2),
                "file_offset": f"0x{fileOffset:x}",
                "init_prot": initProt,
                "max_prot": maxProt
            })

        # Read all images
        f.seek(imagesOffset)
        images = []
        for i in range(imagesCount):
            ibytes = f.read(32)
            address, modTime, inode, pathFileOffset, pad = struct.unpack("<QQQII", ibytes)
            cur = f.tell()
            f.seek(pathFileOffset)
            path_bytes = b""
            while True:
                c = f.read(1)
                if c == b"\x00" or not c:
                    break
                path_bytes += c
            f.seek(cur)
            images.append({
                "index": i,
                "address": f"0x{address:x}",
                "path": path_bytes.decode("utf-8", errors="replace")
            })

    return {
        "magic": magic,
        "mapping_count": mappingCount,
        "mappings": mappings,
        "image_count": imagesCount,
        "images": images,
        "code_signature_offset": f"0x{codeSignatureOffset:x}",
        "code_signature_size": codeSignatureSize,
        "slide_info_offset": f"0x{slideInfoOffset:x}",
        "slide_info_size": slideInfoSize
    }

def main():
    print("=== Mach-O Static Binary Analysis ===")
    results = {}

    for name, path in TARGET_BINARIES.items():
        if not os.path.exists(path):
            print(f"[-] Missing binary: {path}")
            continue
        print(f"[+] Analyzing {name} ({path})...")
        hinfo = compute_hashes(path)

        if name == "dyld_shared_cache":
            cache_info = parse_dyld_cache(path)
            results[name] = {
                "file_info": hinfo,
                "cache_info": cache_info
            }
            print(f"    dyld cache with {cache_info['image_count']} images, {cache_info['mapping_count']} mappings")
        else:
            macho_info = parse_macho_header_and_load_commands(path)
            results[name] = {
                "file_info": hinfo,
                "macho_info": macho_info
            }
            hdr = macho_info.get("header", {})
            print(f"    Mach-O {hdr.get('magic')} {hdr.get('cputype')} ({hdr.get('filetype')}) - {macho_info.get('load_commands_count')} load commands")

    out_file = "analysis/symbols/macho_structures.json"
    os.makedirs(os.path.dirname(out_file), exist_ok=True)
    with open(out_file, "w") as f:
        json.dump(results, f, indent=2)
    print(f"[+] Successfully wrote Mach-O structures to {out_file}")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
extract_objc_metadata.py
Extracts complete Objective-C runtime metadata from Apple TV (tvOS 13.4.8) Mach-O binaries.
Dumps class declarations, hierarchies, method lists, protocols, ivars, and properties.
Strictly static analysis - zero execution of ARM64 binaries.
"""

import os
import sys
import json
import re
import subprocess

TARGET_APPS = {
    "PineBoard": "extracted/rootfs/Applications/PineBoard.app/PineBoard",
    "HeadBoard": "extracted/rootfs/Applications/HeadBoard.app/HeadBoard",
    "PreBoard": "extracted/rootfs/Applications/PreBoard.app/PreBoard",
    "TVMusic": "extracted/rootfs/Applications/TVMusic.app/TVMusic",
    "TVSystemMenuService": "extracted/rootfs/Applications/TVSystemMenuService.app/TVSystemMenuService",
    "TVPeripheralAgent": "extracted/rootfs/Applications/TVPeripheralAgent.app/TVPeripheralAgent",
}

def parse_objc_dump(filepath):
    """Run llvm-objdump --macho --objc-meta-data and parse output structure."""
    cmd = ["llvm-objdump", "--macho", "--objc-meta-data", filepath]
    proc = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    if proc.returncode != 0:
        print(f"[-] Error running llvm-objdump on {filepath}: {proc.stderr}")
        return []

    lines = proc.stdout.splitlines()
    classes = []

    current_class = None
    section_state = None  # "baseMethods", "classMethods", "ivars", "baseProperties", "baseProtocols"
    current_item = None
    is_metaclass = False

    for line in lines:
        stripped = line.strip()

        # Check start of a class entry: e.g. "00000001002e10f8 0x100342d50"
        if re.match(r"^[0-9a-fA-F]{16}\s+0x[0-9a-fA-F]+", line) and "Contents of" not in line:
            if current_class and current_class.get("name"):
                classes.append(current_class)
            current_class = {
                "class_addr": line.split()[0],
                "isa": None,
                "superclass": None,
                "name": None,
                "protocols": [],
                "ivars": [],
                "properties": [],
                "instance_methods": [],
                "class_methods": []
            }
            section_state = None
            is_metaclass = False
            continue

        if current_class is None:
            continue

        # Look for metaclass block
        if "Meta Class" in line or (stripped.startswith("isa ") and "0x" in stripped and current_class.get("name")):
            is_metaclass = True
            section_state = None

        if stripped.startswith("superclass "):
            sc = stripped.split("superclass ", 1)[1].strip()
            # If line is like "0x0 _OBJC_CLASS_$_NSObject" or "0x100342cb8 PBSystemOverlaySession"
            sc_parts = sc.split()
            if len(sc_parts) > 1:
                sc_name = sc_parts[1].replace("_OBJC_CLASS_$_", "")
                if not is_metaclass and not current_class["superclass"]:
                    current_class["superclass"] = sc_name
            elif sc == "0x0":
                if not is_metaclass and not current_class["superclass"]:
                    current_class["superclass"] = "NSObject"

        elif stripped.startswith("name ") and "baseMethods" not in line and "baseProtocols" not in line:
            name_val = stripped.split()[-1]
            if section_state == "baseMethods" or section_state == "classMethods":
                if current_item is not None:
                    current_item["name"] = name_val
            elif section_state == "ivars":
                if current_item is not None:
                    current_item["name"] = name_val
            elif section_state == "baseProperties":
                if current_item is not None:
                    current_item["name"] = name_val
            elif section_state == "baseProtocols":
                if name_val not in current_class["protocols"]:
                    current_class["protocols"].append(name_val)
            else:
                if not current_class["name"]:
                    current_class["name"] = name_val

        elif stripped.startswith("baseMethods "):
            section_state = "classMethods" if is_metaclass else "baseMethods"
            current_item = None
        elif stripped.startswith("baseProtocols "):
            section_state = "baseProtocols"
            current_item = None
        elif stripped.startswith("ivars "):
            section_state = "ivars"
            current_item = None
        elif stripped.startswith("baseProperties "):
            section_state = "baseProperties"
            current_item = None

        elif section_state in ("baseMethods", "classMethods"):
            if stripped.startswith("name "):
                if current_item and current_item.get("name"):
                    if section_state == "classMethods":
                        current_class["class_methods"].append(current_item)
                    else:
                        current_class["instance_methods"].append(current_item)
                current_item = {"name": stripped.split()[-1]}
            elif stripped.startswith("types ") and current_item is not None:
                current_item["types"] = stripped.split()[-1]
            elif stripped.startswith("imp ") and current_item is not None:
                current_item["imp"] = stripped.split()[-1]

        elif section_state == "ivars":
            if stripped.startswith("name "):
                if current_item and current_item.get("name"):
                    current_class["ivars"].append(current_item)
                current_item = {"name": stripped.split()[-1]}
            elif stripped.startswith("type ") and current_item is not None:
                current_item["type"] = stripped.split(None, 1)[1]
            elif stripped.startswith("offset ") and current_item is not None:
                current_item["offset"] = stripped.split()[-1]
            elif stripped.startswith("size ") and current_item is not None:
                current_item["size"] = stripped.split()[-1]

        elif section_state == "baseProperties":
            if stripped.startswith("name "):
                if current_item and current_item.get("name"):
                    current_class["properties"].append(current_item)
                current_item = {"name": stripped.split()[-1]}
            elif stripped.startswith("attributes ") and current_item is not None:
                current_item["attributes"] = stripped.split(None, 1)[1]

    # Flush last item/class
    if current_item and current_item.get("name"):
        if section_state == "classMethods":
            current_class["class_methods"].append(current_item)
        elif section_state == "baseMethods":
            current_class["instance_methods"].append(current_item)
        elif section_state == "ivars":
            current_class["ivars"].append(current_item)
        elif section_state == "baseProperties":
            current_class["properties"].append(current_item)

    if current_class and current_class.get("name"):
        classes.append(current_class)

    # Deduplicate classes by name
    dedup = {}
    for c in classes:
        name = c["name"]
        if not name:
            continue
        if name not in dedup:
            dedup[name] = c
        else:
            # merge methods / ivars
            existing = dedup[name]
            for m in c["instance_methods"]:
                if m not in existing["instance_methods"]:
                    existing["instance_methods"].append(m)
            for m in c["class_methods"]:
                if m not in existing["class_methods"]:
                    existing["class_methods"].append(m)
            for iv in c["ivars"]:
                if iv not in existing["ivars"]:
                    existing["ivars"].append(iv)
            for pr in c["properties"]:
                if pr not in existing["properties"]:
                    existing["properties"].append(pr)
            for proto in c["protocols"]:
                if proto not in existing["protocols"]:
                    existing["protocols"].append(proto)
            if not existing["superclass"] and c["superclass"]:
                existing["superclass"] = c["superclass"]

    return list(dedup.values())

def format_objc_header(cls):
    """Format an Objective-C class dictionary as clean ObjC interface declaration."""
    name = cls["name"]
    superclass = cls["superclass"] or "NSObject"
    protocols = f" <{', '.join(cls['protocols'])}>" if cls["protocols"] else ""

    lines = [f"@interface {name} : {superclass}{protocols}"]

    if cls["ivars"]:
        lines.append("{")
        for iv in cls["ivars"]:
            iv_type = iv.get("type", "id")
            iv_name = iv.get("name", "ivar")
            lines.append(f"    {iv_type} {iv_name};")
        lines.append("}")

    if cls["properties"]:
        for prop in cls["properties"]:
            pname = prop.get("name", "prop")
            attrs = prop.get("attributes", "")
            lines.append(f"@property (attributes: \"{attrs}\") id {pname};")

    if cls["class_methods"]:
        lines.append("// Class Methods")
        for m in cls["class_methods"]:
            mname = m.get("name", "method")
            imp = m.get("imp", "0x0")
            types = m.get("types", "")
            lines.append(f"+ (id){mname}; // imp: {imp}, types: {types}")

    if cls["instance_methods"]:
        lines.append("// Instance Methods")
        for m in cls["instance_methods"]:
            mname = m.get("name", "method")
            imp = m.get("imp", "0x0")
            types = m.get("types", "")
            lines.append(f"- (id){mname}; // imp: {imp}, types: {types}")

    lines.append("@end\n")
    return "\n".join(lines)

def main():
    print("=== Extracting Objective-C Runtime Metadata ===")
    os.makedirs("analysis/objc", exist_ok=True)
    all_objc_data = {}

    for app_name, app_path in TARGET_APPS.items():
        if not os.path.exists(app_path):
            print(f"[-] Missing binary: {app_path}")
            continue
        print(f"[+] Processing {app_name} ({app_path})...")
        classes = parse_objc_dump(app_path)
        print(f"    Found {len(classes)} Objective-C classes in {app_name}")

        # Save formatted classes.txt
        txt_path = f"analysis/objc/{app_name}_classes.txt"
        with open(txt_path, "w") as f:
            f.write(f"// Objective-C Class Dump: {app_name}\n")
            f.write(f"// Binary: {app_path}\n")
            f.write(f"// Total Classes: {len(classes)}\n\n")
            for c in sorted(classes, key=lambda x: x["name"]):
                f.write(format_objc_header(c))
                f.write("\n")

        all_objc_data[app_name] = {
            "binary": app_path,
            "class_count": len(classes),
            "classes": classes
        }

    # Save complete JSON
    json_path = "analysis/objc/objc_classes.json"
    with open(json_path, "w") as f:
        json.dump(all_objc_data, f, indent=2)
    print(f"[+] Successfully wrote {json_path}")

    # Generate OBJC_CLASS_INDEX.md
    index_md = "analysis/objc/OBJC_CLASS_INDEX.md"
    with open(index_md, "w") as f:
        f.write("# Objective-C Runtime Class Index & Taxonomy\n\n")
        f.write("Extracted via non-destructive static analysis from tvOS 13.4.8 (Build 17M61) system applications.\n\n")
        f.write("## Overview of Recovered Applications\n\n")
        f.write("| Application | Binary Path | Recovered Classes | Primary Frameworks / Protocols |\n")
        f.write("|---|---|---|---|\n")
        for app_name, data in all_objc_data.items():
            f.write(f"| **{app_name}** | `{data['binary']}` | {data['class_count']} | UIKit, PineBoardServices, FrontBoardServices |\n")
        f.write("\n---\n\n")

        for app_name, data in all_objc_data.items():
            f.write(f"## {app_name} Class Roster ({data['class_count']} classes)\n\n")
            f.write("| Class Name | Superclass | Protocols Conformed | Methods (Inst/Class) | Ivars |\n")
            f.write("|---|---|---|---|---|\n")
            for c in sorted(data["classes"], key=lambda x: x["name"]):
                protos = ", ".join(c["protocols"]) if c["protocols"] else "none"
                n_inst = len(c["instance_methods"])
                n_cls = len(c["class_methods"])
                n_iv = len(c["ivars"])
                f.write(f"| `{c['name']}` | `{c['superclass'] or 'NSObject'}` | {protos} | {n_inst} / {n_cls} | {n_iv} |\n")
            f.write("\n---\n\n")

    print(f"[+] Successfully generated {index_md}")

if __name__ == "__main__":
    main()

